import Department from "../models/Department.js";
import Field from "../models/Field.js";
import ResearchPaper from "../models/ResearchPaper.js";
import Faculty from "../models/Faculty.js";
import Event from "../models/Event.js";

// The chatbot works in two modes:
//  1. Rule-based mode (default, no API key needed) — matches the visitor's
//     message against departments/fields/keywords and returns real records
//     pulled straight from the database, with short generated replies.
//  2. LLM mode — if OPENAI_API_KEY is set in .env, replies are generated by
//     an LLM with the same database context passed in as grounding, so
//     answers stay factual instead of hallucinated.
// This means the chatbot is fully functional immediately after `npm run seed`,
// and gets noticeably smarter the moment a key is added — no code changes needed.

const extractKeywords = (text) =>
  text
    .toLowerCase()
    .replace(/[^\w\s]/g, "")
    .split(/\s+/)
    .filter((w) => w.length > 2);

const buildContext = async (keywords) => {
  const regexes = keywords.map((k) => new RegExp(k, "i"));

  const [departments, fields, papers, faculty, events] = await Promise.all([
    Department.find({ name: { $in: regexes } }).limit(5),
    Field.find({ name: { $in: regexes } }).limit(5),
    ResearchPaper.find({ $or: [{ title: { $in: regexes } }, { tags: { $in: keywords } }] })
      .populate("department", "name")
      .populate("field", "name")
      .limit(5),
    Faculty.find({ name: { $in: regexes } }).populate("department", "name").limit(5),
    Event.find({ title: { $in: regexes } }).limit(5),
  ]);

  return { departments, fields, papers, faculty, events };
};

const ruleBasedReply = (message, context) => {
  const { departments, fields, papers, faculty, events } = context;

  if (papers.length) {
    const list = papers.map((p) => `"${p.title}" (${p.department?.name || "—"}, ${p.field?.name || "—"})`);
    return {
      text: `I found ${papers.length} research paper(s) that match: ${list.join("; ")}.`,
      suggestions: papers.map((p) => ({ label: p.title, type: "research", id: p._id })),
    };
  }
  if (faculty.length) {
    const list = faculty.map((f) => `${f.name} (${f.department?.name || "—"})`);
    return {
      text: `Here's faculty matching your question: ${list.join("; ")}.`,
      suggestions: faculty.map((f) => ({ label: f.name, type: "faculty", id: f._id })),
    };
  }
  if (departments.length) {
    return {
      text: `The ${departments[0].name} department is on RIDS — you can browse all of its research from the Departments page.`,
      suggestions: departments.map((d) => ({ label: d.name, type: "department", id: d._id })),
    };
  }
  if (fields.length) {
    return {
      text: `${fields[0].name} is one of our 10 knowledge fields — I can show you research tagged under it.`,
      suggestions: fields.map((f) => ({ label: f.name, type: "field", id: f._id })),
    };
  }
  if (events.length) {
    return {
      text: `Upcoming/related events: ${events.map((e) => e.title).join(", ")}.`,
      suggestions: events.map((e) => ({ label: e.title, type: "event", id: e._id })),
    };
  }

  return {
    text:
      "I couldn't find an exact match for that. Try asking about a department (e.g. \"Agriculture research\"), a field (e.g. \"SDG papers\"), or a faculty member by name.",
    suggestions: [],
  };
};

const llmReply = async (message, context) => {
  const contextSummary = JSON.stringify({
    departments: context.departments.map((d) => d.name),
    fields: context.fields.map((f) => f.name),
    papers: context.papers.map((p) => ({ title: p.title, dept: p.department?.name, field: p.field?.name })),
    faculty: context.faculty.map((f) => ({ name: f.name, dept: f.department?.name })),
  });

  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content:
            "You are the RIDS research-discovery assistant for a university. Only answer using the provided database context. If the context is empty, say you couldn't find a match and suggest what to search instead. Keep answers to 2-3 sentences.",
        },
        { role: "user", content: `Context: ${contextSummary}\n\nVisitor question: ${message}` },
      ],
      max_tokens: 200,
    }),
  });

  if (!response.ok) throw new Error(`OpenAI API error: ${response.status}`);
  const data = await response.json();
  return { text: data.choices[0].message.content, suggestions: [] };
};

export const getChatbotReply = async (message) => {
  const keywords = extractKeywords(message);
  const context = await buildContext(keywords);

  if (process.env.OPENAI_API_KEY) {
    try {
      return await llmReply(message, context);
    } catch (err) {
      console.error("LLM chatbot call failed, falling back to rule-based reply:", err.message);
      return ruleBasedReply(message, context);
    }
  }

  return ruleBasedReply(message, context);
};
